def operations(a,b, c):
    results = 0
    if b== "+":
       results = a + c
    elif b== "-":
        results = a - c
    elif b== "/":
        if c != 0:
            results = a / c
        else:
            print("The value is incorrect")
    elif b == "*":
        results = a * c
    else:
        print("The value is incorrect")
    return results
